import { useContext, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import loginimg from '../image/phishing.webp'
import AttendancenSApi from '../../ContextAPi/AttendanceSApi'

const Student = () => {
  const context = useContext(AttendancenSApi)
  const { showAlert, bgcolor } = context
  const isDark = bgcolor === 'dark'

  const [credintial, setMycredintial] = useState({ email: '', password: '' })
  const [showPass, setShowPass] = useState(false)
  const [loading, setLoading] = useState(false)
  const navigate = useNavigate()

  const handleChange = (e) => {
    setMycredintial({ ...credintial, [e.target.name]: e.target.value })
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setLoading(true)
    try {
      const response = await fetch('http://localhost:5000/api/student/studentlogin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: credintial.email,
          password: credintial.password,
        }),
      })
      const json = await response.json()
      if (json.success) {
        localStorage.setItem('token', json.authtoken)
        showAlert('Login Successfully', 'success')
        navigate('/studentdata')
      } else {
        showAlert('Invalid Credenital', 'danger')
      }
    } catch (err) {
      showAlert('Cannot reach the server. Try again.', 'danger')
    } finally {
      setLoading(false)
    }
  }

  const handleHelp = () => {
    showAlert(
      'Enter your Roll Number as email or password is your Date of Birth',
      'info'
    )
  }

  // ---- theme classes (full strings so Tailwind can detect them) ----
  const shell = isDark
   ? 'bg-gradient-to-br from-slate-950 via-slate-900 to-indigo-950'
    : 'bg-gradient-to-br from-slate-50 via-white to-blue-50'
  const heading = isDark ? 'text-slate-50' : 'text-slate-900'
  const muted = isDark ? 'text-slate-400' : 'text-slate-500'
  const label = isDark ? 'text-slate-200' : 'text-slate-700'
  const input = isDark
    ? 'bg-slate-900 border-slate-600 text-slate-100 placeholder-slate-500 focus:border-blue-400 focus:ring-blue-400/30'
    : 'bg-white border-slate-300 text-slate-900 placeholder-slate-400 focus:border-blue-500 focus:ring-blue-500/30'
  const link = isDark
    ? 'text-blue-300 hover:text-blue-200'
    : 'text-blue-600 hover:text-blue-700'

  return (
    <div className="mx-auto flex max-w-5xl px-4 py-6">
      <div
        className={`grid w-full overflow-hidden rounded-3xl shadow-xl md:grid-cols-2 ${shell}`}
      >
        {/* Image panel */}
        <div className="relative hidden md:block">
          <img
            src={loginimg}
            alt="Secure student login illustration"
            className="absolute inset-0 h-full w-full object-cover"
          />
        </div>

        {/* Form panel */}
        <div className="flex items-center justify-center p-8 sm:p-12">
          <form onSubmit={handleSubmit} className="w-full max-w-sm" noValidate>
            <h1 className={`text-2xl font-semibold tracking-tight ${heading}`}>
              Student login
            </h1>
            <p className={`mt-1 text-sm ${muted}`}>
              Sign in to see your attendance records.
            </p>

            <div className="mt-8 space-y-5">
              <div>
                <label htmlFor="email" className={`mb-1.5 block text-sm font-medium ${label}`}>
                  Username or roll number
                </label>
                <input
                  type="text"
                  id="email"
                  name="email"
                  value={credintial.email}
                  onChange={handleChange}
                  autoComplete="username"
                  required
                  placeholder="e.g. 21CS104"
                  className={`w-full rounded-xl border px-4 py-2.5 text-sm outline-none transition focus:ring-4 ${input}`}
                />
              </div>

              <div>
                <label htmlFor="password" className={`mb-1.5 block text-sm font-medium ${label}`}>
                  Password
                </label>
                <div className="relative">
                  <input
                    type={showPass ? 'text' : 'password'}
                    id="password"
                    name="password"
                    value={credintial.password}
                    onChange={handleChange}
                    autoComplete="current-password"
                    required
                    placeholder="Enter your password"
                    className={`w-full rounded-xl border py-2.5 pl-4 pr-16 text-sm outline-none transition focus:ring-4 ${input}`}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPass((s) => !s)}
                    className={`absolute inset-y-0 right-3 text-xs font-medium ${link}`}
                  >
                    {showPass ? 'Hide' : 'Show'}
                  </button>
                </div>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading || !credintial.email || !credintial.password}
              className="mt-7 flex w-full items-center justify-center rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700 focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-blue-500/40 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {loading ? 'Signing in…' : 'Login'}
            </button>

            <button
              type="button"
              onClick={handleHelp}
              className={`mt-5 block w-full text-center text-sm font-medium ${link}`}
            >
              Need help signing in?
            </button>
          </form>
        </div>
      </div>
    </div>
  )
}

export default Student
